
        // ═══════════════════════════════════════════════════
        //  SPACE BATTLE – SOUND
        // ═══════════════════════════════════════════════════
        const SFX_EXPLOSION_B64 = 'data:audio/mp3;base64,';
        function playExplosion() {
            try {
                const a = new Audio(SFX_EXPLOSION_B64);
                a.volume = 0.55;
                a.play().catch(()=>{});
            } catch(e) {}
        }

        // ═══════════════════════════════════════════════════
        //  SPACE BATTLE  –  math-powered shoot-em-up
        // ═══════════════════════════════════════════════════
        const IMG_SHIP1 = 'data:image/png;base64,';
        const IMG_SHIP2 = 'data:image/png;base64,';
        const IMG_SHIP3 = 'data:image/png;base64,';
        const IMG_SHIP4 = 'data:image/png;base64,';
        const IMG_SHIP5 = 'data:image/png;base64,';
        const IMG_SHIP6 = 'data:image/png;base64,';

        const SPACE_SHIPS = [
            { src:IMG_SHIP1, label:'Scout',       size:62,  baseSpeed:0.55, reward:6,  tier:1, rot:'90deg'  },
            { src:IMG_SHIP2, label:'Raider',      size:74,  baseSpeed:0.48, reward:14, tier:2, rot:'180deg' },
            { src:IMG_SHIP3, label:'Bomber',      size:82,  baseSpeed:0.42, reward:26, tier:3, rot:'-90deg' },
            { src:IMG_SHIP4, label:'Warship',     size:90,  baseSpeed:0.36, reward:44, tier:4, rot:'-90deg' },
            { src:IMG_SHIP5, label:'Dreadnought', size:102, baseSpeed:0.30, reward:70, tier:5, rot:'180deg' },
            { src:IMG_SHIP6, label:'Overlord',    size:116, baseSpeed:0.24, reward:120,tier:6, rot:'180deg' },
        ];

        let sg = null; // active space-game state

        // Simple math questions keyed by tier difficulty
        function genSpaceQ(tier) {
            const r = (a,b) => Math.floor(Math.random()*(b-a+1))+a;
            let q='', a;
            if (tier === 1) {
                const x=r(1,25),y=r(1,25);
                if(Math.random()<0.5) { q=`${x} + ${y}`; a=x+y; }
                else { const hi=Math.max(x,y),lo=Math.min(x,y); q=`${hi} − ${lo}`; a=hi-lo; }
            } else if (tier === 2) {
                const x=r(2,12),y=r(2,12); q=`${x} × ${y}`; a=x*y;
            } else if (tier === 3) {
                const x=r(2,25),y=r(2,x); q=`${x*y} ÷ ${y}`; a=x;
            } else if (tier === 4) {
                const x=r(2,9); q=`${x}²`; a=x*x;
            } else if (tier === 5) {
                const c=r(3,20),ans=r(2,30); q=`x + ${c} = ${ans+c}`; a=ans;
            } else {
                const x=r(3,12),y=r(3,12),z=r(1,15); q=`${x} × ${y} − ${z}`; a=x*y-z;
            }
            return { q, a };
        }

        function showSpaceGame() {
            hideAll();
            document.getElementById('bottom-nav').style.display='none';
            const sec=document.getElementById('section-space');
            sec.classList.remove('hidden');
            startSpaceGame();
        }

        function exitSpaceGame() {
            stopSpaceGame();
            document.getElementById('section-space').classList.add('hidden');
            document.getElementById('bottom-nav').style.display='';
            showDashboard();
        }

        function startSpaceGame() {
            const arena=document.getElementById('sg-arena');
            if(arena) arena.innerHTML='';
            const sgu = user.spaceUpgrades || {};
            sg = {
                lives: sgu.sg_shield ? 4 : 3,
                wave:1, score:0,
                enemies:[], selected:null,
                running:true, uid:0,
                waveTotal:0, waveSpawned:0,
                loopId:null, spawnId:null,
                speedMult: sgu.sg_laser  ? 0.80 : 1.0,
                rewardMult: sgu.sg_magnet ? 1.75 : 1.0,
                spawnMult:  sgu.sg_hyper  ? 1.35 : 1.0,
            };
            buildStarfield();
            renderSgHud();
            beginWave();
        }

        function stopSpaceGame() {
            if(!sg) return;
            sg.running=false;
            if(sg.loopId) { cancelAnimationFrame(sg.loopId); sg.loopId=null; }
            if(sg.spawnId) { clearInterval(sg.spawnId); sg.spawnId=null; }
            sg=null;
        }

        function renderSgHud() {
            if(!sg) return;
            document.getElementById('sg-score').innerText = sg.score.toLocaleString();
            document.getElementById('sg-wave-lbl').innerText = 'WAVE ' + sg.wave;
            const lv=document.getElementById('sg-lives');
            lv.innerHTML='';
            for(let i=0;i<3;i++) {
                const s=document.createElement('span');
                s.innerText=i<sg.lives?'❤️':'🖤'; s.style.opacity=i<sg.lives?'1':'0.35';
                lv.appendChild(s);
            }
        }

        function buildStarfield() {
            const arena=document.getElementById('sg-arena');
            for(let i=0;i<90;i++) {
                const s=document.createElement('div'); s.className='space-star';
                const sz=Math.random()*2.4+0.4;
                s.style.cssText=`width:${sz}px;height:${sz}px;left:${Math.random()*100}%;top:${Math.random()*100}%;opacity:${Math.random()*0.65+0.1};animation-duration:${Math.random()*18+7}s;animation-delay:-${Math.random()*20}s;`;
                arena.appendChild(s);
            }
            // Player ship at bottom
            const pl=document.createElement('div'); pl.className='space-player'; pl.id='sg-player'; pl.innerText='🚀';
            pl.style.left='50%';
            arena.appendChild(pl);
            arena.addEventListener('mousemove', e=>{
                const r=arena.getBoundingClientRect();
                const pct=((e.clientX-r.left)/r.width*100).toFixed(1);
                const p=document.getElementById('sg-player');
                if(p) p.style.left=Math.min(95,Math.max(5,pct))+'%';
            });
        }

        function beginWave() {
            if(!sg) return;
            sg.waveTotal = 5 + sg.wave * 3;
            sg.waveSpawned = 0;
            const interval = Math.max(700, (2600 - sg.wave * 160) * sg.spawnMult);
            spawnEnemy();
            sg.waveSpawned = 1;
            sg.spawnId = setInterval(()=>{
                if(!sg||!sg.running) return;
                if(sg.waveSpawned >= sg.waveTotal) { clearInterval(sg.spawnId); sg.spawnId=null; return; }
                spawnEnemy(); sg.waveSpawned++;
            }, interval);
            gameLoop();
        }

        function pickTier() {
            const max=Math.min(6, sg.wave);
            const weights=[];
            for(let i=0;i<max;i++) weights.push(max-i);
            const total=weights.reduce((a,b)=>a+b,0);
            let r=Math.random()*total;
            for(let i=0;i<weights.length;i++) { r-=weights[i]; if(r<=0) return i; }
            return 0;
        }

        function spawnEnemy() {
            if(!sg) return;
            const arena=document.getElementById('sg-arena');
            if(!arena) return;
            const tier=pickTier();
            const ship=SPACE_SHIPS[tier];
            const qd=genSpaceQ(tier+1);
            const id=++sg.uid;
            const left=Math.random()*78+5;

            const el=document.createElement('div');
            el.className='enemy-ship';
            el.id='sgship-'+id;
            el.style.cssText=`left:${left}%; top:-${ship.size+60}px;`;
            el.innerHTML=`<div class="enemy-q-label">${qd.q} = ?</div><img class="enemy-img" src="${ship.src}" style="width:${ship.size}px; transform:rotate(${ship.rot});" />`;
            el.addEventListener('click',()=>selectSgEnemy(id,qd,el));
            arena.appendChild(el);

            const spd = ship.baseSpeed * (1 + (sg.wave-1)*0.12) * sg.speedMult;
            sg.enemies.push({ id, el, ship, qd, y:-(ship.size+60), spd, paused:false });
        }

        function gameLoop() {
            if(!sg||!sg.running) return;
            const arena=document.getElementById('sg-arena');
            if(!arena) { return; }
            const h=arena.offsetHeight;

            for(let i=sg.enemies.length-1; i>=0; i--) {
                const e=sg.enemies[i];
                if(e.paused) continue;
                e.y += e.spd;
                e.el.style.top = e.y+'px';
                if(e.y > h - 20) {
                    if(e.el.parentNode) e.el.parentNode.removeChild(e.el);
                    sg.enemies.splice(i,1);
                    if(sg.selected&&sg.selected.id===e.id) cancelSgAnswer();
                    sg.lives--;
                    renderSgHud();
                    sgHullBreachEffect();
                    if(sg.lives<=0) { sgGameOver(); return; }
                }
            }

            // Wave cleared?
            if(sg.waveSpawned>=sg.waveTotal && sg.enemies.length===0 && sg.running) {
                sgWaveClear(); return;
            }
            sg.loopId = requestAnimationFrame(gameLoop);
        }

        function selectSgEnemy(id, qd, el) {
            if(!sg||sg.selected) return;
            sg.selected={id,qd};
            const en=sg.enemies.find(e=>e.id===id);
            if(en) en.paused=true;
            el.style.filter='drop-shadow(0 0 22px rgba(99,102,241,1)) brightness(1.4)';

            const arena=document.getElementById('sg-arena');
            const panel=document.createElement('div');
            panel.id='sg-panel'; panel.className='space-answer-panel';
            panel.innerHTML=`
                <div class="space-answer-q">${qd.q} = ?</div>
                <input id="sg-inp" class="space-answer-input" type="number" inputmode="decimal" placeholder="?" />
                <div class="space-btn-row">
                    <button class="space-btn space-btn-fire" onclick="submitSgAnswer()">FIRE 🔥</button>
                    <button class="space-btn space-btn-cancel" onclick="cancelSgAnswer()">Cancel</button>
                </div>`;
            arena.appendChild(panel);
            setTimeout(()=>{
                const inp=document.getElementById('sg-inp');
                if(inp){ inp.focus(); inp.addEventListener('keydown',e=>{ if(e.key==='Enter') submitSgAnswer(); }); }
            },50);
        }

        function submitSgAnswer() {
            if(!sg||!sg.selected) return;
            const inp=document.getElementById('sg-inp');
            if(!inp) return;
            const val=parseFloat(inp.value.trim());
            const {id,qd}=sg.selected;
            if(val===qd.a) {
                // Correct — destroy
                const idx=sg.enemies.findIndex(e=>e.id===id);
                if(idx>=0) {
                    const en=sg.enemies[idx];
                    const r=en.el.getBoundingClientRect();
                    const ar=document.getElementById('sg-arena').getBoundingClientRect();
                    sgExplode(r.left-ar.left+r.width/2, r.top-ar.top+r.height/2);
                    playExplosion();
                    if(en.el.parentNode) en.el.parentNode.removeChild(en.el);
                    sg.enemies.splice(idx,1);
                    const earned=Math.round(en.ship.reward * sg.rewardMult);
                    sg.score+=earned;
                    if(user){ user.coins+=earned; user.weeklyScore=(user.weeklyScore||0)+earned; save(); updateUI(); }
                    renderSgHud();
                }
                playCorrect();
            } else {
                // Wrong — unpause and flash red
                const en=sg.enemies.find(e=>e.id===id);
                if(en){
                    en.paused=false;
                    en.el.style.filter='drop-shadow(0 0 18px rgba(239,68,68,1)) brightness(1.5)';
                    setTimeout(()=>{ if(en.el) en.el.style.filter=''; },700);
                }
                playWrong();
            }
            sg.selected=null;
            const panel=document.getElementById('sg-panel');
            if(panel) panel.remove();
        }

        function cancelSgAnswer() {
            if(!sg||!sg.selected) return;
            const en=sg.enemies.find(e=>e.id===sg.selected.id);
            if(en){ en.paused=false; en.el.style.filter=''; }
            sg.selected=null;
            const panel=document.getElementById('sg-panel');
            if(panel) panel.remove();
        }


        function sgHullBreachEffect() {
            const arena = document.getElementById('sg-arena');
            if(!arena) return;
            // Red overlay flash
            const ov = document.createElement('div'); ov.className='sg-red-overlay';
            arena.appendChild(ov);
            ov.addEventListener('animationend', ()=>ov.remove());
            // Hull breach text
            const txt = document.createElement('div'); txt.className='sg-hull-breach';
            txt.innerText = sg.lives === 1 ? '⚠ CRITICAL DAMAGE ⚠' : '— HULL BREACH —';
            arena.appendChild(txt);
            txt.addEventListener('animationend', ()=>txt.remove());
            // Arena shake
            arena.style.animation='arena-shake 0.5s ease-out';
            arena.addEventListener('animationend', ()=>{ arena.style.animation=''; }, {once:true});
        }

        function sgDeathSpectacle() {
            const arena = document.getElementById('sg-arena');
            if(!arena) return;
            const cx = arena.offsetWidth/2, cy = arena.offsetHeight/2;
            const colors=['#EF4444','#F97316','#FCD34D','#ffffff'];
            for(let i=0;i<5;i++) {
                const ring = document.createElement('div'); ring.className='sg-death-ring';
                const sz = 80+i*60;
                ring.style.cssText=`width:${sz}px;height:${sz}px;left:${cx}px;top:${cy}px;border:4px solid ${colors[i%colors.length]};animation-delay:${i*0.12}s;`;
                arena.appendChild(ring);
                ring.addEventListener('animationend',()=>ring.remove());
            }
            for(let i=0;i<20;i++) sgExplode(cx+Math.random()*200-100, cy+Math.random()*200-100);
        }

        function sgExplode(cx,cy) {
            const arena=document.getElementById('sg-arena');
            if(!arena) return;
            const colors=['#F59E0B','#F97316','#EF4444','#FCD34D','#ffffff','#A78BFA'];
            // Expanding rings
            for(let i=0;i<4;i++) {
                const ring=document.createElement('div'); ring.className='sg-ring';
                const sz=30+i*38;
                ring.style.cssText=`width:${sz}px;height:${sz}px;left:${cx-sz/2}px;top:${cy-sz/2}px;background:${colors[i%colors.length]};animation-delay:${i*0.06}s;`;
                arena.appendChild(ring);
                ring.addEventListener('animationend',()=>ring.remove());
            }
            // Debris particles
            for(let i=0;i<16;i++) {
                const d=document.createElement('div'); d.className='sg-debris';
                const angle=(i/16)*Math.PI*2;
                const dist=55+Math.random()*80;
                d.style.cssText=`width:${Math.random()*8+4}px;height:${Math.random()*8+4}px;left:${cx}px;top:${cy}px;background:${colors[i%colors.length]};--dx:${(Math.cos(angle)*dist).toFixed(1)}px;--dy:${(Math.sin(angle)*dist).toFixed(1)}px;--dr:${Math.random()*720-360}deg;--dur:${(0.4+Math.random()*0.35).toFixed(2)}s;`;
                arena.appendChild(d);
                d.addEventListener('animationend',()=>d.remove());
            }
        }

        function sgWaveClear() {
            sg.running=false;
            if(sg.loopId){ cancelAnimationFrame(sg.loopId); sg.loopId=null; }
            if(sg.spawnId){ clearInterval(sg.spawnId); sg.spawnId=null; }
            sg.wave++;
            const arena=document.getElementById('sg-arena');
            const ov=document.createElement('div'); ov.className='space-overlay';
            ov.innerHTML=`<h2>WAVE ${sg.wave-1} CLEARED!</h2><p>Score: ${sg.score.toLocaleString()} Gold &nbsp;·&nbsp; Next: Wave ${sg.wave}</p>
                <button class="main-btn" onclick="sgNextWave()" style="margin:0 auto 12px;display:block;">WAVE ${sg.wave} →</button>
                <button class="main-btn btn-ghost" onclick="exitSpaceGame()" style="margin:0 auto;display:block;">Retreat</button>`;
            arena.appendChild(ov);
            launchConfetti(50); playFanfare(false);
        }

        function sgNextWave() {
            const ov=document.querySelector('#sg-arena .space-overlay');
            if(ov) ov.remove();
            const panel=document.getElementById('sg-panel');
            if(panel) panel.remove();
            sg.enemies=[]; sg.selected=null; sg.running=true;
            beginWave();
        }

        function sgGameOver() {
            sg.running=false;
            if(sg.loopId){ cancelAnimationFrame(sg.loopId); sg.loopId=null; }
            if(sg.spawnId){ clearInterval(sg.spawnId); sg.spawnId=null; }
            sgDeathSpectacle();
            const arena=document.getElementById('sg-arena');
            const ov=document.createElement('div'); ov.className='space-overlay';
            ov.innerHTML=`<div style="font-size:64px;margin-bottom:14px;">💥</div><h2>SHIP DESTROYED</h2>
                <p>Wave ${sg.wave} &nbsp;·&nbsp; ${sg.score.toLocaleString()} Gold earned</p>
                <button class="main-btn" onclick="startSpaceGame()" style="margin:0 auto 12px;display:block;">TRY AGAIN</button>
                <button class="main-btn btn-ghost" onclick="exitSpaceGame()" style="margin:0 auto;display:block;">Retreat</button>`;
            setTimeout(()=>arena.appendChild(ov), 900);
            playFail();
        }

